/* GitHub DNA — Primer: familiar dev surfaces, link blue, precise grays, 6px radius */
.theme-github-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.978 0.003 247.9);
  --surface-2: oklch(0.947 0.007 247.9);
  --fg: oklch(0.254 0.011 254.0);
  --fg-muted: oklch(0.495 0.022 250.8);
  --accent: oklch(0.540 0.191 257.5);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.563 0.207 295.0);
  --line: oklch(0.881 0.013 244.3);
  --success: oklch(0.524 0.140 148.0);
  --warning: oklch(0.554 0.117 75.0);
  --danger: oklch(0.552 0.205 24.5);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Mona Sans", sans-serif;
  --font-body: "Mona Sans", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.02em;
  --label-transform: none;
  --label-tracking: 0.04em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-github-dna h1,
.theme-github-dna h2,
.theme-github-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-github-dna { --font-ui: var(--font-display); }
.theme-github-dna h1 { font-weight: 600; letter-spacing: -0.02em; }
.theme-github-dna kbd { border-bottom-width: 3px; }

/* depth */
.theme-github-dna thead th { background: var(--surface); border-bottom: 1px solid var(--line); font-size: 0.75rem; font-weight: 600; color: var(--fg-muted); }
.theme-github-dna td { border-bottom: 1px solid var(--line); }
.theme-github-dna tbody tr:hover { background: var(--surface); }
.theme-github-dna a { color: var(--accent); text-decoration: none; }
.theme-github-dna a:hover { text-decoration: underline; }
.theme-github-dna input, .theme-github-dna select, .theme-github-dna textarea { background: var(--bg); border: 1px solid oklch(0.78 0.02 250); transition: border-color 80ms ease, box-shadow 80ms ease; }
.theme-github-dna input:focus-visible, .theme-github-dna select:focus-visible, .theme-github-dna textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px oklch(0.54 0.19 257 / 30%); }
.theme-github-dna kbd { font-family: var(--font-mono); font-size: 0.6875rem; background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-sm); padding: 0.15em 0.5em; box-shadow: inset 0 -1px 0 var(--line); }
.theme-github-dna ::selection { background: oklch(0.54 0.19 257 / 25%); }
.theme-github-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-github-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-github-dna ::-webkit-scrollbar-thumb { background: color-mix(in oklab, var(--fg-muted) 45%, transparent); border-radius: var(--radius-pill); }
.theme-github-dna .label-caps { font-size: 0.75rem; font-weight: 600; color: var(--fg-muted); }
.theme-github-dna .themed-border { border-color: var(--line); border-radius: var(--radius); box-shadow: var(--shadow-1); }
.theme-github-dna button:active { box-shadow: inset 0 1px 0 oklch(0 0 0 / 10%); }
.theme-github-dna button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

/* alt mode: GitHub dark default — #0d1117 dimmed palette, not generic black */
.theme-github-dna.alt-mode {
  --bg: oklch(0.163 0.014 262);
  --surface: oklch(0.202 0.016 260);
  --surface-2: oklch(0.245 0.020 258);
  --fg: oklch(0.884 0.006 250);
  --fg-muted: oklch(0.640 0.020 252);
  --accent: oklch(0.712 0.143 254);
  --accent-fg: oklch(0.130 0.010 260);
  --line: oklch(0.320 0.020 255);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
